+const test = require('node:test');
+const assert = require('node:assert/strict');
+
+const {
+  calculateScores,
+  generateResult,
+  RESULT_TYPES,
+} = require('../miniprogram/utils/result-engine');
+
+test('calculates dimension scores from selected answers', () => {
+  const answers = ['q1_a', 'q2_b', 'q3_c'];
+
+  const scores = calculateScores(answers);
+
+  assert.equal(scores.energy, 4);
+  assert.equal(scores.pressure, 5);
+  assert.equal(scores.social, 2);
+  assert.equal(scores.patience, 1);
+  assert.equal(scores.escape, 3);
+});
+
+test('returns a safe fallback result for empty answers', () => {
+  const result = generateResult([]);
+
+  assert.equal(result.type, '低电量续航型');
+  assert.equal(result.score, 52);
+  assert.deepEqual(result.tags, ['低电量', '慢慢来', '先保命']);
+});
+
+test('maps high pressure and low energy to quiet crash result', () => {
+  const result = generateResult(['q1_c', 'q2_c', 'q3_a', 'q4_c', 'q5_c', 'q6_c', 'q7_c', 'q8_c']);
+
+  assert.equal(result.type, '静音崩溃型');
+  assert.ok(result.score >= 76);
+  assert.equal(result.riskLabel, '高压');
+});
+
+test('every configured result type can be produced by a fixture', () => {
+  const fixtures = {
+    静音崩溃型: ['q1_c', 'q2_c', 'q3_a', 'q4_c', 'q5_c', 'q6_c', 'q7_c', 'q8_c'],
+    假装在线型: ['q1_b', 'q2_b', 'q3_b', 'q4_b', 'q5_a', 'q6_b', 'q7_b', 'q8_b'],
+    会议耗尽型: ['q1_b', 'q2_c', 'q3_a', 'q4_c', 'q5_b', 'q6_c', 'q7_b', 'q8_c'],
+    下班倒计时型: ['q1_a', 'q2_a', 'q3_c', 'q4_a', 'q5_c', 'q6_a', 'q7_c', 'q8_a'],
+    低电量续航型: ['q1_c', 'q2_a', 'q3_b', 'q4_b', 'q5_b', 'q6_a', 'q7_b', 'q8_a'],
+    周一重启失败型: ['q1_c', 'q2_b', 'q3_c', 'q4_a', 'q5_a', 'q6_c', 'q7_a', 'q8_c'],
+    表面稳定型: ['q1_a', 'q2_b', 'q3_b', 'q4_b', 'q5_b', 'q6_b', 'q7_b', 'q8_b'],
+    已读乱回型: ['q1_b', 'q2_b', 'q3_c', 'q4_b', 'q5_b', 'q6_b', 'q7_c', 'q8_b'],
+  };
+
+  for (const type of RESULT_TYPES) {
+    assert.equal(generateResult(fixtures[type]).type, type);
+  }
+});
